#!/usr/bin/env node
/* gen-freshness.mjs — the S17 A3 freshness map: ONE freshness.json that maps every GENERATED file
 * to the sha256 of every input it reads, so a planted or drifted receipt byte turns the claims
 * gate RED with the changed file NAMED (the work order's gate: "plant a changed receipt byte →
 * freshness.json, the status line and the claims gate all turn RED; restore → all green").
 *
 * Generated files mapped here and their ACTUAL inputs (read the generators — no guessed inputs):
 *   SHELL-STATUS.md  ← tools/shell-status.mjs reads: SNAPSHOT.md (the pin), src/App.svelte (the
 *                      seed lines), ACCEPTANCE-RECEIPTS.txt (the acceptance-run pointer +
 *                      acceptanceSha), deliveries/receipts/visual-battery-latest.json and
 *                      slot-battery-latest.json (the freshness verdicts), every dist/ file (the
 *                      content fingerprint), plus the LIVE battery runs (not files).
 *   README.md / ZAI.md / deliveries/zai-s15-closeout-handover-2026-11-21.md (the GENERATED state
 *                      blocks only — the docs' human text is outside the markers)
 *                      ← claims.json + every claim's SUBJECT bytes: CHECKSUMS.txt is deliberately
 *                      EXCLUDED from this map (a file cannot be an input to a map that the seal
 *                      seals — self-reference); ACCEPTANCE-RECEIPTS.txt (acceptance claims), the
 *                      two battery receipts, node-battery.log, the side-by-side receipt, and the
 *                      two boot docs (the 2026-11-24 currency claims) are inputs.
 *   acceptanceSha    ← sha256(ACCEPTANCE-RECEIPTS.txt) at generation time; SHELL-STATUS prints the
 *                      same value and the freshnessMap claim recomputes all three (map / status /
 *                      live receipt) and REDs on any mismatch.
 *
 * Usage: node scripts/gen-freshness.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';

const ROOT = path.resolve(new URL('..', import.meta.url).pathname);
const sha = (rel) => createHash('sha256').update(fs.readFileSync(path.join(ROOT, rel))).digest('hex');
const exists = (rel) => fs.existsSync(path.join(ROOT, rel));

const ACC = 'ACCEPTANCE-RECEIPTS.txt';
const VIS = 'deliveries/receipts/visual-battery-latest.json';
const SLOT = 'deliveries/receipts/slot-battery-latest.json';
const SBS = 'deliveries/receipts/s15-side-by-side.json';
const NB = 'deliveries/receipts/node-battery.log';
const HANDOVER = 'deliveries/zai-s15-closeout-handover-2026-11-21.md';

const inputs = {
  // the SHELL-STATUS inputs are the files tools/shell-status.mjs actually reads (the pin, the seed
  // lines, the acceptance pointer + acceptanceSha, the two freshness receipts) plus the dist walk.
  'SHELL-STATUS.md': ['SNAPSHOT.md', 'src/App.svelte', ACC, VIS, SLOT],
  // the three state-block docs: exactly the inputs whose BYTES the rendered claim lines depend on
  // (claims.json the descs; ACC the acceptance claims; the side-by-side + battery receipts the
  // sideBySide/statusFreshness/node-battery lines). Docs that are only REGEX-claimed (ZAI.md,
  // START, the package note, the inbox filing) are deliberately ABSENT — the block never re-hashes
  // them, and recording them would self-loop (writing the block changes ZAI.md → README's record
  // goes stale → the block regenerates → …).
  'README.md': ['claims.json', ACC, SBS, NB, VIS, SLOT],
  'ZAI.md': ['claims.json', ACC, SBS, NB, VIS, SLOT],
  [HANDOVER]: ['claims.json', ACC, SBS, NB, VIS, SLOT],
};
const files = {};
const missing = [];
for (const [gen, ins] of Object.entries(inputs)) {
  const rec = { inputs: {} };
  for (const i of ins) {
    if (!exists(i)) { missing.push(`${gen} input ${i}`); continue; }
    rec.inputs[i] = sha(i);
  }
  // the dist fingerprint — SHELL-STATUS's content-freshness input — recorded as one derived value
  if (gen === 'SHELL-STATUS.md') {
    const h = createHash('sha256');
    const walk = (d) => { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else h.update(path.relative(ROOT, p) + ':' + createHash('sha256').update(fs.readFileSync(p)).digest('hex') + '\n'); } };
    walk(path.join(ROOT, 'dist'));
    rec.distFingerprint = h.digest('hex');
  }
  files[gen] = rec;
}
const out = {
  meta: 'GENERATED by scripts/gen-freshness.mjs — do not edit; regenerate at the final bytes (the receipt law: if the state changes, the receipts are rewritten). Each entry maps a GENERATED file to the sha256 of every input it reads; acceptanceSha is sha256(ACCEPTANCE-RECEIPTS.txt). CHECKSUMS.txt is deliberately absent (self-reference).',
  generated: new Date().toISOString().replace(/\.\d+Z$/, 'Z'),
  acceptanceSha: sha(ACC),
  files,
};
fs.writeFileSync(path.join(ROOT, 'freshness.json'), JSON.stringify(out, null, 1) + '\n');
console.log(`gen-freshness: freshness.json written (${Object.keys(files).length} generated files, acceptanceSha ${out.acceptanceSha.slice(0, 16)}…${missing.length ? '; MISSING inputs: ' + missing.join(', ') : ''})`);
if (missing.length) process.exit(1);
